import numpy as np
from PIL import Image
import json, os

def load(path):
    im = Image.open(path).convert('RGB')
    return np.array(im), im.size  # arr[H,W,3], (W,H)

def top_colors(arr, n=20, exclude_near_white=True, exclude_near_black=False):
    a = arr.reshape(-1,3).astype(int)
    if exclude_near_white:
        # drop near-white
        mask = ~((a[:,0]>235)&(a[:,1]>235)&(a[:,2]>235))
        a = a[mask]
    # quantize to buckets
    q = (a//8)*8
    uniq, counts = np.unique(q, axis=0, return_counts=True)
    idx = np.argsort(-counts)[:n]
    for i in idx:
        c = uniq[i]
        print(f"  rgb~({c[0]},{c[1]},{c[2]}) count={counts[i]}")

def calib(x1,p1,v1,x2,p2,v2,px,scale):
    if scale=='linear':
        return v1 + (px-p1)*(v2-v1)/(p2-p1)
    else:
        return 10**(np.log10(v1) + (px-p1)*(np.log10(v2)-np.log10(v1))/(p2-p1))

def get_tasks():
